CREATE TABLE [dbo].[RIA_NETWORKCREDENTIALS](	  [id] INT NOT NULL IDENTITY(1,1)	, [domain] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [user] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [password] VARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [status] TINYINT NOT NULL DEFAULT('')	, [type] TINYINT NULL DEFAULT((1)))